proxy.caddy:
# Caddy reference config for nzbget, generated by the hub from its image.yml.
# Caddy and the nzbget container share a docker network; replace example.com with your domain.
# Caddy fetches the certificate and passes websockets through on its own.

nzbget.example.com {
	# API paths stay open so client applications keep working.
	@api path /jsonrpc /jsonrpc/* /jsonprpc /jsonprpc/* /xmlrpc /xmlrpc/*
	handle @api {
		reverse_proxy nzbget:6789
